def get_boll(close_data, n=20, m=2):
    close_df = close_data[-n:]
    middle = close_df[:].sum() / n
    upper = middle + m * close_df[:].std(ddof=1)
    lower = middle - m * close_df[:].std(ddof=1)
    width = (upper - middle) / middle
    return (upper, middle, lower)
