def get_strategy_finance_factor_info(factor_select_before_info, factor_sort_before_info):
    strategy_finance_factor_info = defaultdict(set)
    def add_to_strategy_info(factor_info_list):
        for factor_info in factor_info_list:
            if factor_info.get('factor_type') == 'valuation':
                factor = factor_info['factor']
                if factor in COMBINATION_FACTOR_INFO:
                    comb_factor_list = COMBINATION_FACTOR_INFO[factor]
                    for factor in comb_factor_list:
                        table = WIZARD_QUANT_FINANCE_FIELD_FACTOR_INFO[factor]['jy_table']
                        jy_factor = WIZARD_QUANT_FINANCE_FIELD_FACTOR_INFO[factor]['jy_factor']
                        strategy_finance_factor_info[table].add(jy_factor)
                    continue
                table = WIZARD_QUANT_FINANCE_FIELD_FACTOR_INFO[factor]['jy_table']
                jy_factor = WIZARD_QUANT_FINANCE_FIELD_FACTOR_INFO[factor]['jy_factor']
                strategy_finance_factor_info[table].add(jy_factor)
            continue
    return {table: list(factors) for table, factors in strategy_finance_factor_info.items()}
def get_strategy_turnover_ratio_factor_max_count(factor_select_before_info, factor_sort_before_info, transac_buy_info, transac_sell_info):
    max_turnover_ratio_count_list = []
    def add_to_strategy_info(factor_info_list):
        for factor_info in factor_info_list:
            factor = factor_info['factor']
            if factor == 'last_turnover_ratio':
                max_turnover_ratio_count_list.append(1)
                continue
            elif factor in ('turnover_ratio_n_days_ago', 'turnover_ratio_mean_n_days'):
                max_turnover_ratio_count_list.append(int(factor_info['algo_params'].split(':')[-1]))
    add_to_strategy_info(factor_select_before_info)
    add_to_strategy_info(factor_sort_before_info)
    add_to_strategy_info(transac_buy_info)
    add_to_strategy_info(transac_sell_info)
    if max_turnover_ratio_count_list:
        max_turnover_ratio_count = max(max_turnover_ratio_count_list)
    else:
        max_turnover_ratio_count = 0
    return max_turnover_ratio_count
def wizard_quant_check_limit(security, last_close_array, high_limit_array, low_limit_array):
    if isinstance(security, six.string_types):
        security = [security]
    return_data = dict()
    for stock in security:
        return_data[stock] = 0
        try:
            if last_close_array is None:
                continue
            elif len(last_close_array) < 1:
                continue
            else:
                stock_close = last_close_array[-1]
                if high_limit_array is None:
                    continue
                elif len(high_limit_array) < 1:
                    continue
                else:
                    stock_high_limit = high_limit_array[-1]
                    if low_limit_array is None:
                        continue
                    elif len(low_limit_array) < 1:
                        continue
                    else:
                        stock_low_limit = low_limit_array[-1]
                        if stock_high_limit == stock_close:
                            return_data[stock] = 1
                            continue
                        elif stock_low_limit == stock_close:
                            return_data[stock] = -1
                            continue
        except:
            continue
    else:
        return return_data
def get_data_flag(factor_config_list):
    special_factor = ['last_turnover_ratio', 'turnover_ratio_n_days_ago', 'turnover_ratio_mean_n_days', 'listing_days']
    def check_factor(factor_info_list):
        for factor_info in factor_info_list:
            if factor_info.get('factor_type') == 'data' and factor_info.get('factor') not in special_factor:
                return True
            if factor_info.get('factor_type') == 'tech':
                return True
        return False
    for factor_config in factor_config_list:
        flag = check_factor(factor_config)
        if flag:
            return True
    else:
        return False
